import { render, screen } from "@testing-library/react";
import { SubscriberList } from "./SubscriberList";
import { createSubscriber } from "../testing/factories";

describe("SubscriberList", () => {
  it("renders no list items for an empty subscribers array", () => {
    render(<SubscriberList subscribers={[]} />);

    expect(screen.queryAllByRole("listitem")).toHaveLength(0);
  });

  it("links each subscriber's email address", () => {
    render(<SubscriberList subscribers={[createSubscriber({ email: "ada@example.com" })]} />);

    expect(screen.getByRole("link", { name: "ada@example.com" })).toHaveAttribute(
      "href",
      "mailto:ada@example.com",
    );
  });

  it("renders a subscriber's topics joined by comma", () => {
    render(
      <SubscriberList
        subscribers={[createSubscriber({ topics: ["engineering", "product"] })]}
      />,
    );

    expect(screen.getByText("engineering, product")).toBeVisible();
  });

  it("renders each subscriber's name", () => {
    const subscribers = [
      createSubscriber({ id: "s1", name: "Ada Lovelace" }),
      createSubscriber({ id: "s2", name: "Grace Hopper" }),
    ];

    render(<SubscriberList subscribers={subscribers} />);

    expect(screen.getByText("Ada Lovelace")).toBeVisible();
    expect(screen.getByText("Grace Hopper")).toBeVisible();
  });
});

import type { Subscriber } from "../testing/factories";

interface SubscriberListProps {
  subscribers: Subscriber[];
}

export function SubscriberList({ subscribers }: SubscriberListProps) {
  return (
    <ul>
      {subscribers.map((subscriber) => (
        <li key={subscriber.id}>
          <span>{subscriber.name}</span>
          <a href={`mailto:${subscriber.email}`}>{subscriber.email}</a>
          <span>{subscriber.topics.join(", ")}</span>
        </li>
      ))}
    </ul>
  );
}
